from ledgerly.adjustments import refund_shipping
from ledgerly.models import Payment
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(): return Payment("p","i",Decimal("100.00"),status="captured",created_at=T0,captured_at=T0)

# partial then full
p=mk(); refund_shipping(p,Decimal("40"),T0); assert p.refunded_amount==Decimal("40.00") and p.status=="captured"
refund_shipping(p,Decimal("60"),T0); assert p.refunded_amount==Decimal("100.00") and p.status=="refunded"
print("partial/full ok")

# over refund
p=mk()
try: refund_shipping(p,Decimal("101"),T0); print("FAIL")
except BillingError as e: print("over:",e.code)

# non-positive
for bad in [Decimal("0"), Decimal("-1"), True, "abc"]:
    p=mk()
    try: refund_shipping(p,bad,T0); print("FAIL",bad)
    except BillingError as e: print("bad",repr(bad),e.code)

# approval
p=mk()
try: refund_shipping(p,Decimal("500.01"),T0); print("FAIL")
except BillingError as e: print("approval:",e.code)
refund_shipping(p,Decimal("500.01"),T0,approved_by="mgr"); print("approved ok")

# idempotency
p=mk(); refund_shipping(p,Decimal("10"),T0,idempotency_key="k1")
refund_shipping(p,Decimal("10"),T0,idempotency_key="k1")
assert p.refunded_amount==Decimal("10.00"); print("idempotent ok")

# invalid state
p=mk(); p.status="authorized"
try: refund_shipping(p,Decimal("1"),T0); print("FAIL")
except BillingError as e: print("state:",e.code)
